(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-032":{scenario:{company:"Indigo Harbor Fintech",supervisor:{name:"Vũ Thanh Tâm",role:{vi:"Giám đốc Giao hàng Dự án",en:"Delivery Director"}},ref_code:"SPR-1907",title:{vi:"Bảo vệ Sprint Goal. Dự báo bằng dữ liệu thật.",en:"Protect the Sprint Goal. Forecast with real data."},brief:{vi:"Bạn là Scrum Master của đội 7 lập trình viên làm ví điện tử, chuẩn bị Sprint Planning cho sprint 19 (10 ngày làm việc). Velocity Done của 3 sprint gần nhất: 41, 36, 40 điểm. Sprint 19 có nghỉ lễ và nghỉ phép nên đội chỉ còn 60/70 ngày công. Giữa sprint 18, khối kinh doanh đòi đưa ngay yêu cầu mới CR-77 vào sprint. Đối chiếu kế hoạch nháp với quy ước làm việc đã duyệt, sửa nơi tiếp nhận CR-77 và dự báo năng lực sprint 19, rồi lập báo cáo có căn cứ.",en:"You are the Scrum Master of a 7-developer e-wallet team preparing Sprint Planning for sprint 19 (10 working days). Done velocity of the last 3 sprints: 41, 36 and 40 points. Holidays and leave leave the team only 60 of 70 person-days in sprint 19. Mid sprint 18, Sales demanded that new request CR-77 go straight into the sprint. Compare the draft plan with the approved working agreement, fix where CR-77 goes and the sprint 19 forecast, then write an evidence-based report."},reference_title:{vi:"Quy ước làm việc & quy tắc dự báo đã duyệt · SPR-1907",en:"Approved working agreement & forecasting rule · SPR-1907"},fields:[{id:"CR77_ROUTE",label:{vi:"Nơi tiếp nhận yêu cầu CR-77",en:"Where CR-77 is placed"},initial:"Sprint Backlog",expected:"Product Backlog",choices:["Sprint Backlog","Product Backlog","Sprint Cancel"],reference:"Quy ước làm việc của đội",hint:{vi:"Việc mới phải vào nơi do Product Owner sắp xếp thứ tự; không đẩy thẳng vào sprint đang chạy làm lệch Sprint Goal.",en:"New work goes where the Product Owner orders it; never push it into a running sprint against the Sprint Goal."}},{id:"FORECAST_SP",label:{vi:"Dự báo năng lực sprint 19 (điểm)",en:"Sprint 19 forecast (points)"},initial:"41",expected:"33",reference:"Quy tắc dự báo năng lực",ref_value:{vi:"Velocity Done 3 sprint: 41, 36, 40; ngày công sprint 19: 60/70; làm tròn xuống",en:"Done velocity of 3 sprints: 41, 36, 40; sprint 19 person-days: 60/70; round down"},hint:{vi:"Dùng trung bình velocity của các story đạt DoD, rồi điều chỉnh theo ngày công thực có của sprint tới.",en:"Use the average velocity of stories meeting the DoD, then scale by the person-days actually available next sprint."}}],sop32:{vi:"Dự báo = trung bình velocity Done của 3 sprint gần nhất x (ngày công khả dụng / ngày công chuẩn), làm tròn xuống; không lấy sprint cao nhất, không tính story chưa đạt DoD.",en:"Forecast = average Done velocity of the last 3 sprints x (available person-days / standard person-days), rounded down; never use the best sprint or count stories that miss the DoD."},context:{label:"SCRUM BOARD / SPR-1907",metrics:[{label:{vi:"Velocity 3 sprint",en:"Velocity, 3 sprints"},value:"41 / 36 / 40"},{label:{vi:"Ngày công khả dụng",en:"Available person-days"},value:"60 / 70"},{label:{vi:"Độ dài sprint (ngày)",en:"Sprint length (days)"},value:"10"}]},crisis:{vi:"Giám đốc khách hàng nhắn: “Sprint Review mai cứ báo 3 story thanh toán chưa qua kiểm thử là Done để khách ký nghiệm thu mốc 2 và chuyển tiền. Sprint sau sửa nốt.”",en:"The account director messages you: “At tomorrow's Sprint Review, report the 3 untested payment stories as Done so the client signs milestone 2 and pays. We will finish them next sprint.”"},options:{safe:{vi:"Chỉ trình bày phần tăng trưởng đạt Definition of Done, nêu rõ 3 story chưa xong; báo Giám đốc giao hàng và Product Owner, đề xuất nghiệm thu lại có điều kiện.",en:"Show only the increment that meets the Definition of Done and state the 3 unfinished stories; inform the Delivery Director and Product Owner and propose a conditional re-acceptance."},shortcut:{vi:"Báo 3 story là Done để khách ký nghiệm thu, sprint sau âm thầm sửa nốt.",en:"Report the 3 stories as Done for the sign-off and quietly finish them next sprint."},wait:{vi:"Không chuẩn bị gì, để giám đốc khách hàng tự trình bày với khách.",en:"Prepare nothing and let the account director present to the client alone."}},questions:{vi:["Vì sao CR-77 phải vào Product Backlog và dự báo sprint 19 là 33 điểm? Bạn dùng dữ liệu nào để chứng minh?","Nếu bị ép báo story chưa đạt DoD là Done để nghiệm thu, bạn giữ minh bạch với khách hàng và xử lý rủi ro hợp đồng thế nào?"],en:["Why must CR-77 go to the Product Backlog and the sprint 19 forecast be 33 points? Which data proves it?","If pressed to report stories that miss the DoD as Done for sign-off, how do you stay transparent with the client and handle the contract risk?"]},hints:{vi:["Xem lại ai có quyền sắp xếp thứ tự công việc và điều gì bảo vệ Sprint Goal đang chạy.","Tính trung bình velocity trước, sau đó nhân tỷ lệ ngày công theo SOP mục 3.2.","Đọc lại SOP mục 4.2: chỉ phần tăng trưởng đạt Definition of Done mới được trình bày là hoàn thành."],en:["Check who may order the work and what protects the running Sprint Goal.","Average the velocity first, then apply the person-day ratio in SOP 3.2.","Re-read SOP 4.2: only an increment meeting the Definition of Done may be presented as done."]}},learning:{summary:{vi:"Quản lý dự án phần mềm Agile hay Scrum Master giúp đội phát triển giao giá trị đều đặn qua các sprint ngắn: điều phối sự kiện Scrum, gỡ trở ngại, minh bạch tiến độ và cải tiến liên tục cách làm việc. Họ phối hợp chặt với Product Owner để quản lý backlog, phạm vi, rủi ro và kỳ vọng của khách hàng. Nghề đòi hỏi hiểu sâu khung Agile, kỹ năng coaching, đo lường bằng dữ liệu và chính trực khi báo cáo.",en:"An Agile project manager or Scrum Master helps the team deliver value steadily in short sprints: facilitating Scrum events, removing impediments, making progress transparent and continuously improving how the team works. They work closely with the Product Owner on backlog, scope, risk and client expectations. The role requires deep Agile knowledge, coaching skills, data-driven measurement and integrity in reporting."},responsibilities:{vi:["Điều phối Sprint Planning, Daily Scrum, Sprint Review, Retrospective đúng mục đích và khung thời gian.","Phát hiện, gỡ trở ngại và bảo vệ đội khỏi gián đoạn ngoài quy trình.","Hỗ trợ Product Owner làm rõ, sắp xếp Product Backlog và quản lý yêu cầu thay đổi.","Theo dõi velocity, burndown, cycle time và dự báo phát hành dựa trên dữ liệu thực.","Quản lý rủi ro, phụ thuộc và báo cáo minh bạch cho khách hàng, ban điều hành."],en:["Facilitate Sprint Planning, Daily Scrum, Sprint Review and Retrospective with clear purpose and timeboxes.","Spot and remove impediments and shield the team from out-of-process interruptions.","Help the Product Owner refine and order the Product Backlog and manage change requests.","Track velocity, burndown and cycle time and forecast releases from real data.","Manage risks and dependencies and report transparently to the client and leadership."]},competencies:[{name:{vi:"Điều phối",en:"Facilitation"},desc:{vi:"Dẫn dắt sự kiện để đội tự đưa ra quyết định, đúng khung thời gian và có kết quả rõ.",en:"Lead events so the team makes its own decisions, within timeboxes and with clear outcomes."}},{name:{vi:"Coaching Agile",en:"Agile coaching"},desc:{vi:"Giúp đội và tổ chức hiểu giá trị Agile, tự quản và cải tiến liên tục.",en:"Help the team and organisation embrace Agile values, self-management and continuous improvement."}},{name:{vi:"Dự báo bằng dữ liệu",en:"Data-driven forecasting"},desc:{vi:"Dùng velocity, thông lượng, cycle time để dự báo có khoảng tin cậy thay vì hứa theo cảm tính.",en:"Use velocity, throughput and cycle time to forecast with ranges instead of gut-feel promises."}},{name:{vi:"Quản lý các bên liên quan",en:"Stakeholder management"},desc:{vi:"Cân bằng kỳ vọng khách hàng, kinh doanh và năng lực đội qua kênh do Product Owner điều phối.",en:"Balance client, sales and team capacity through channels the Product Owner coordinates."}},{name:{vi:"Chính trực & minh bạch",en:"Integrity & transparency"},desc:{vi:"Báo cáo đúng tiến độ và chất lượng, không thổi phồng hay che giấu phần chưa xong.",en:"Report true progress and quality, never inflating or hiding unfinished work."}}],knowledge:{vi:["Scrum Guide 2020: 3 trách nhiệm, 5 sự kiện, 3 artifact cùng các cam kết Product Goal, Sprint Goal, Definition of Done.","Tuyên ngôn Agile 2001: 4 giá trị và 12 nguyên tắc.","Kanban: trực quan hóa, giới hạn WIP, quản lý luồng; định luật Little: cycle time = WIP / thông lượng.","PMBOK Guide ấn bản 7: 12 nguyên tắc và 8 lĩnh vực hiệu suất dự án.","Ước lượng tương đối (story point, planning poker), velocity, biểu đồ burndown và burnup."],en:["Scrum Guide 2020: 3 accountabilities, 5 events, 3 artifacts with the Product Goal, Sprint Goal and Definition of Done commitments.","Agile Manifesto 2001: 4 values and 12 principles.","Kanban: visualisation, WIP limits and flow management; Little's Law: cycle time = WIP / throughput.","PMBOK Guide 7th edition: 12 principles and 8 project performance domains.","Relative estimation (story points, planning poker), velocity, burndown and burnup charts."]},tools:["Bảng Scrum/Kanban điện tử","Công cụ báo cáo burndown","Bảng trắng trực tuyến","Bảng tính","Công cụ họp trực tuyến"],kpis:{vi:["Tỷ lệ sprint đạt Sprint Goal.","Độ ổn định velocity và độ chính xác của dự báo.","Cycle time trung bình từ khi bắt đầu đến khi Done.","Mức hài lòng của đội và khách hàng qua khảo sát định kỳ."],en:["Share of sprints meeting the Sprint Goal.","Velocity stability and forecast accuracy.","Average cycle time from start to Done.","Team and client satisfaction from regular surveys."]},day:[{time:"09:00",vi:"Điều phối Daily Scrum 15 phút, ghi nhận trở ngại mà đội nêu ra.",en:"Facilitate the 15-minute Daily Scrum and note impediments the team raises."},{time:"09:30",vi:"Làm việc với đội hạ tầng để gỡ lỗi môi trường kiểm thử đang chặn 2 story.",en:"Work with the infrastructure team to unblock the test environment holding up 2 stories."},{time:"11:00",vi:"Cùng Product Owner tinh chỉnh backlog, tách story lớn và làm rõ tiêu chí chấp nhận.",en:"Refine the backlog with the Product Owner, split large stories and clarify acceptance criteria."},{time:"14:00",vi:"Cập nhật burndown, sổ rủi ro và trao đổi tiến độ minh bạch với khách hàng.",en:"Update the burndown and risk log and share progress transparently with the client."},{time:"16:00",vi:"Chuẩn bị Retrospective: chọn kỹ thuật, tổng hợp dữ liệu cycle time của sprint.",en:"Prepare the Retrospective: pick a format and gather the sprint's cycle time data."}],mistakes:{vi:["Lập kế hoạch theo velocity cao nhất hoặc tính cả story chưa đạt Definition of Done.","Cho các bên liên quan đẩy việc thẳng vào sprint đang chạy, bỏ qua Product Owner.","Biến Daily Scrum thành buổi báo cáo cho quản lý thay vì để đội tự lập kế hoạch trong ngày."],en:["Planning on the best velocity or counting stories that miss the Definition of Done.","Letting stakeholders push work straight into a running sprint, bypassing the Product Owner.","Turning the Daily Scrum into a status report for managers instead of the team's own daily plan."]},career:[{vi:"Điều phối viên dự án / thành viên đội phát triển",en:"Project coordinator / development team member"},{vi:"Scrum Master",en:"Scrum Master"},{vi:"Agile Coach / quản lý dự án cấp cao",en:"Agile Coach / senior project manager"},{vi:"Giám đốc giao hàng / trưởng PMO Agile",en:"Delivery director / head of Agile PMO"}],glossary:[{term:"Sprint Goal",vi:"Mục tiêu duy nhất của sprint, tạo sự tập trung và linh hoạt về cách đạt được.",en:"The single objective of a sprint that creates focus while allowing flexibility in how it is met."},{term:"Definition of Done",vi:"Mô tả chính thức trạng thái của phần tăng trưởng khi đạt chuẩn chất lượng để được coi là hoàn thành.",en:"Formal description of the state of the increment when it meets the quality bar to count as done."},{term:"Velocity",vi:"Tổng điểm của các story đạt Definition of Done trong một sprint, dùng để dự báo.",en:"Total points of stories meeting the Definition of Done in a sprint, used for forecasting."},{term:"WIP limit",vi:"Giới hạn số việc đang làm cùng lúc để giảm chuyển đổi ngữ cảnh và rút ngắn thời gian chu trình.",en:"Cap on work in progress that reduces context switching and shortens cycle time."},{term:"Burndown chart",vi:"Biểu đồ khối lượng công việc còn lại theo thời gian trong sprint hoặc bản phát hành.",en:"Chart of remaining work over time in a sprint or release."}],quiz:[{q:{vi:"Velocity Done 3 sprint gần nhất là 30, 32, 34; sprint tới đội có 45/50 ngày công. Theo quy tắc làm tròn xuống, dự báo là bao nhiêu điểm?",en:"Done velocity of the last 3 sprints is 30, 32 and 34; next sprint has 45 of 50 person-days. Rounding down, what is the forecast?"},options:{vi:["34 điểm","32 điểm","28 điểm","29 điểm"],en:["34 points","32 points","28 points","29 points"]},answer:2,explain:{vi:"Trung bình 32 x 45/50 = 28,8, làm tròn xuống được 28 điểm.",en:"Average 32 x 45/50 = 28.8, rounded down to 28 points."}},{q:{vi:"Theo Scrum Guide 2020, ai chịu trách nhiệm sắp xếp thứ tự Product Backlog?",en:"Under the Scrum Guide 2020, who is accountable for ordering the Product Backlog?"},options:{vi:["Product Owner","Scrum Master","Developers","Khách hàng"],en:["Product Owner","Scrum Master","Developers","The client"]},answer:0,explain:{vi:"Product Owner chịu trách nhiệm quản lý hiệu quả Product Backlog, gồm cả việc sắp xếp thứ tự.",en:"The Product Owner is accountable for effective Product Backlog management, including ordering it."}},{q:{vi:"Bạn bị yêu cầu báo story chưa qua kiểm thử là Done để khách ký nghiệm thu. Cách xử lý đúng là gì?",en:"You are asked to report untested stories as Done so the client signs off. What is the right response?"},options:{vi:["Báo Done rồi sửa ở sprint sau","Không nói gì trong Sprint Review","Hoãn Sprint Review sang tuần sau","Chỉ trình bày phần đạt DoD, báo cấp trên và đề xuất nghiệm thu lại có điều kiện"],en:["Report Done and fix next sprint","Say nothing at the Sprint Review","Postpone the Sprint Review a week","Show only DoD-compliant work, escalate and propose a conditional re-acceptance"]},answer:3,explain:{vi:"Minh bạch là trụ cột của Scrum; báo sai trạng thái để nhận thanh toán là gian dối với khách hàng.",en:"Transparency is a pillar of Scrum; misreporting status to get paid deceives the client."}},{q:{vi:"Bảng Kanban có trung bình 12 việc đang làm, thông lượng 4 việc mỗi tuần. Cycle time trung bình là bao lâu?",en:"A Kanban board averages 12 items in progress with a throughput of 4 items per week. What is the average cycle time?"},options:{vi:["48 tuần","3 tuần","0,33 tuần","16 tuần"],en:["48 weeks","3 weeks","0.33 weeks","16 weeks"]},answer:1,explain:{vi:"Định luật Little: cycle time = WIP / thông lượng = 12 / 4 = 3 tuần.",en:"Little's Law: cycle time = WIP / throughput = 12 / 4 = 3 weeks."}}],tools_en:["Digital Scrum/Kanban board","Burndown reporting tools","Online whiteboard","Spreadsheets","Online meeting tools"]}}})})(window.KKR);
